const payload = $json.body || $json;
const message = (payload.message || payload.question || payload.text || payload.chatInput || '').trim();
const topicSlug = payload.topicSlug || null;

if (!message) {
  return [{ json: { answer: 'No question provided.', question: '', sources: [] } }];
}

// Extract keywords for SQL search
const keywords = message
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, '')
  .split(/\s+/)
  .filter(w => w.length > 3)
  .sort((a, b) => b.length - a.length)
  .slice(0, 5);

return [{ json: { message, topicSlug, keywords, has_question: true } }];

