const rows = $input.all().map(i => i.json);
const questionData = $('Normalize Chat Input').first().json;
const question = questionData.message;

let context;
if (!rows.length || !rows[0].id) {
  context = 'No relevant articles found in the database.';
} else {
  const parts = rows.filter(r => r.id).map((r, i) => {
    const date = r.published_at
      ? new Date(r.published_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
      : 'Date N/A';
    const content = (r.content || r.summary || '').slice(0, 500);
    return `[Source ${i + 1}]\nTitle: ${r.title}\nSource: ${r.source}\nDate: ${date}\nURL: ${r.url}\nContent: ${content}`;
  });
  context = parts.join('\n\n---\n\n');
}

const sources = rows.filter(r => r.id).map(r => ({
  title: r.title, url: r.url, source: r.source, score: 0.5
}));

const seen = new Set();
const uniqueSources = sources.filter(s => {
  if (seen.has(s.url)) return false;
  seen.add(s.url);
  return true;
});

return [{ json: { context, question, sources: uniqueSources } }];

